// ---------- 答题记录存储（错题本、学习进度、经验值都从这里算） ----------
let dbRef = null;
const LOCAL = typeof claude === "undefined";   // 在 GitHub Pages 等普通网页里打开
// 记录存在这台设备的浏览器里，每种记录一个键
function localDb(ns) {
  const key = c => `${ns}-db-${c}`;
  const load = c => { try { return JSON.parse(localStorage.getItem(key(c)) || "[]"); } catch (e) { return []; } };
  const snap = arr => ({ size: arr.length, docs: arr.map(d => ({ data: () => d })) });
  return { collection: c => ({
    add: async d => { const a = load(c); a.push(d); localStorage.setItem(key(c), JSON.stringify(a)); if (typeof syncPush === "function") syncPush(c, d); },
    get: async () => snap(load(c)),
    where: (f, op, v) => ({ get: async () => snap(load(c).filter(d => d[f] === v)) }),
  }) };
}
(async () => {
  try {
    dbRef = LOCAL ? localDb("fq") : await claude.use("db");
    if (!dbRef) { saveNote.textContent = "当前视图无法保存记录，答题不受影响。"; return; }
    const docs = (await dbRef.collection("answers").get()).docs.map(d => d.data());
    let voc = [];
    try { voc = (await dbRef.collection("vocab").get()).docs.map(d => d.data()); } catch (e) {}
    try { gameReset((await dbRef.collection("game").get()).docs.map(d => d.data())); } catch (e) {}
    progReset(docs, voc); progEnsure(); planRefresh();
    if (typeof petOnDataReady === "function") petOnDataReady();
    if (typeof syncNow === "function") syncNow(true);   // 公开网站登录后：和云端同步
    const wrong = docs.filter(d => !d.isCorrect).length;
    saveNote.textContent = wrong ? `已有 ${wrong} 条错题记录，答题记录会自动保存到学习进度。` : "答题记录会自动保存到学习进度。";
    if (LOCAL) saveNote.textContent += "记录保存在这台设备的浏览器里，换设备或清除浏览器数据后不会保留。";
    if (view === "book") renderBook();
    if (view === "cafe" && typeof cafeEnter === "function") cafeEnter();
  } catch (e) { saveNote.textContent = "暂时无法读取答题记录，答题不受影响。"; }
})();
function record(item, i, right) {
  if (typeof funnelStep === "function") funnelStep("answer", item.audio ? "listening" : "grammar");
  if (!dbRef) return;
  const d = {
    round: roundOf(item.id), qid: item.id, ch: item.ch, cat: item.cat, question: item.title ? `（长文听力 · ${item.title}）${item.q}` : item.audio ? "（听力）" + item.audio : item.q,
    chosen: item.opts[i], correct: item.opts[item.a], isCorrect: right, at: new Date().toISOString(),
  };
  dbRef.collection("answers").add(d).catch(() => { saveNote.textContent = "有一条记录没保存成功，答题不受影响。"; });
  progLive(d, "ans");
  bookCache = null;
}
// ---------- 状态 ----------
