  if (key.startsWith("tour:")) return "环法之旅 · " + (typeof tourStop === "function" && tourStop(key.slice(5)) ? stopName(tourStop(key.slice(5))) : key.slice(5)) + " · 语法";
  const p = parseTagKey(key);
