  const parts = PLAN_PARTS.filter(([k]) => p[k].length).map(([k, name]) => ({
    k, name: k === "weak" && p.weakTag ? `弱项「${p.weakTag}」` : name, n: p[k].length, d: p[k].filter(i => done.has(i)).length,
  }));
