// 连续打卡（含补签），从某一天往前数
function streakFrom(day) {
  const by = prog.byDay, xp = d => by[d] || 0, pat = typeof patchedDays === "function" ? patchedDays() : new Set();
  const met = d => xp(d) >= xpGoal || pat.has(d);   // 用补签卡补上的日子也算打卡
  let n = 0, d = day;
  for (let g = 0; g < 3660; g++) {
    if (met(d)) { n++; d = dayOffset(d, -1); continue; }
    // 这一天没达标：第二天达到 2 倍目标、前一天也达标，就算补签
    if (xp(dayOffset(d, 1)) >= 2 * xpGoal && met(dayOffset(d, -1))) { n++; d = dayOffset(d, -1); continue; }
    break;
  }
  return n;
}
function streakInfo() {
  if (!progEnsure()) return { n: 0, today: 0, met: false, patch: 0 };
  const today = dayKey(new Date()), y = dayOffset(today, -1), xp = d => prog.byDay[d] || 0;
  const met = xp(today) >= xpGoal;
  const n = streakFrom(y) + (met ? 1 : 0);
  // 昨天没达标、前天达标：今天达到 2 倍目标就能补签，保住之前的连续天数
  const pat = typeof patchedDays === "function" ? patchedDays() : new Set();
  const patch = xp(y) < xpGoal && !pat.has(y) && (xp(dayOffset(y, -1)) >= xpGoal || pat.has(dayOffset(y, -1))) && xp(today) < 2 * xpGoal ? streakFrom(dayOffset(y, -1)) : 0;
  return { n, today: xp(today), met, patch };
}
// 答完一题后：今天目标刚达成 / 今日计划刚做完时，返回一句大提示
function planNotice(d, todayBefore) {
  const p = planGet();
  if (p) {
    const ids = [...p.review, ...p.fresh, ...p.weak, ...p.listen];
    const s = planStatus(p);
    const hit = d.round === "cj" ? hasConj() && conjToday() === PLAN_CONJ : ids.includes(d.qid);
    if (hit && s.n && s.d === s.n) return "今日计划完成！";
  }
  if (todayBefore < xpGoal && prog.today >= xpGoal) return `今日目标达成！连续 ${streakInfo().n} 天`;
  return "";
}

// 今日计划进度条：宽屏放在目录顶上，窄屏（目录收起时）放在主区域最上面；点了直接开始
