// ---------- 明信片收藏册（游戏模式）：明信片只能在环法之旅里获得（第一次抵达一站就寄来那一站的明信片），集齐一个大区的两张再奖励 150 金币 ----------
// 明信片记成 card 记录（以前在商店买的也照样算），大区奖励记成 earn 记录，都跟着账号同步。环法之旅只在法语页面，所以收藏册也只在法语页面显示。
const ALBUM_BONUS = 150;
const albumOwned = () => gameLedger().cards;
const albumRegionDone = (r, owned) => ALBUM_CARDS.filter(c => c.r === r).every(c => owned.has(c.id));
// 补发集齐大区的奖励（另一台设备集齐的也会在这里补上）
function albumCheck() {
  const led = gameLedger(), out = [];
  ALBUM_REGIONS.forEach(r => {
    if (albumRegionDone(r.id, led.cards) && !led.earned.has("album:" + r.id)) {
      gameAdd({ kind: "earn", key: "album:" + r.id, coins: ALBUM_BONUS, why: `集齐${r.zh}`, at: new Date().toISOString() });
      out.push(r);
    }
  });
  return out;
}
const regionOf = id => ALBUM_REGIONS.find(r => r.id === id);
const albumCardOf = id => ALBUM_CARDS.find(c => c.id === id) || (typeof ALBUM_PARIS !== "undefined" ? ALBUM_PARIS.find(c => c.id === id) : null);
function albumArt(c, cls) { const d = el("div", cls || "pc-art"); d.innerHTML = c.art; return d; }

// 大图：明信片正面是插画，背面是法语介绍（可以朗读、看中文）
function albumView(c) {
  const ov = el("div", "pc-overlay");
  const card = el("div", "pc-big");
  const front = el("div", "pc-front"); front.append(albumArt(c, "pc-art big"), el("span", "pc-hello", c.hello || `Bonjour de ${c.city} !`));
  const back = el("div", "pc-back");
  const reg = regionOf(c.r);
  back.append(el("b", "pc-city", `${c.city} · ${c.zh}`), el("span", "pc-reg", c.paris ? "Paris · Île-de-France · 巴黎" : `${reg.fr} · ${reg.zh}`));
  const fr = el("p", "pc-fr", c.fr), zh = el("p", "pc-zh", c.tr); zh.hidden = true;
  const acts = el("div", "pc-acts");
  if (typeof speak === "function" && typeof tts !== "undefined" && tts) {
    const say = el("button", "btn ghost", "🔊 朗读"); say.type = "button";
    say.addEventListener("click", () => speak(c.fr, .9, say));
    acts.append(say);
  }
  const tr = el("button", "btn ghost", "显示中文"); tr.type = "button";
  tr.addEventListener("click", () => { zh.hidden = !zh.hidden; tr.textContent = zh.hidden ? "显示中文" : "隐藏中文"; });
  const close = el("button", "btn", "关闭"); close.type = "button"; close.id = "pcClose";
  close.addEventListener("click", () => ov.remove());
  acts.append(tr, close);
  back.append(fr, zh, acts);
  card.append(front, back);
  ov.append(card);
  ov.addEventListener("click", e => { if (e.target === ov) ov.remove(); });
  document.body.append(ov);
}
// 刚买到时：明信片背面朝上翻过来
function albumReveal(res) {
  const c = res.card;
  const ov = el("div", "pc-overlay");
  const flip = el("div", "pc-flip");
  const inner = el("div", "pc-flip-in");
  const backFace = el("div", "pc-face pc-face-back"); backFace.append(el("span", "pc-stamp", "POSTE"), el("span", "pc-q", "?"));
  const frontFace = el("div", "pc-face pc-face-front"); frontFace.append(albumArt(c, "pc-art big"), el("span", "pc-hello", c.hello || `Bonjour de ${c.city} !`));
  inner.append(backFace, frontFace); flip.append(inner);
  const msg = el("div", "pc-msg");
  ov.append(flip, msg);
  document.body.append(ov);
  const done = () => {
    msg.append(el("b", null, `新明信片：${c.city} · ${c.zh}`));
    res.bonus.forEach(r => msg.append(el("span", "pc-bonus", `集齐${r.zh}！奖励 ${ALBUM_BONUS} 金币`)));
    const look = el("button", "btn ghost", "看看背面"); look.type = "button";
    look.addEventListener("click", () => { ov.remove(); albumView(c); drawBook(); });
    const ok = el("button", "btn", "放进收藏册"); ok.type = "button"; ok.id = "pcOk";
    ok.addEventListener("click", () => { ov.remove(); drawBook(); });
    const row = el("div", "pc-acts"); row.append(look, ok); msg.append(row);
  };
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) { flip.classList.add("done"); done(); return; }
  requestAnimationFrame(() => { flip.classList.add("go"); setTimeout(() => { flip.classList.add("done"); done(); }, 1000); });
}
function albumCard() {
  if (typeof gameOn !== "function" || !gameOn() || typeof renderTour !== "function") return document.createDocumentFragment();
  albumCheck();
  const led = gameLedger(), owned = led.cards;
  const cityN = ALBUM_CARDS.filter(c => owned.has(c.id)).length;
  const card = el("section", "card album-card");
  const head = el("div", "plan-head");
  head.append(el("h3", null, "明信片收藏册"), el("span", "album-n", `${cityN} / ${ALBUM_CARDS.length}`));
  card.append(head, el("p", "sub", `明信片只能在环法之旅里获得：第一次抵达一座城市（或巴黎的一个区、一个省），就会寄来那里的明信片，背面是一段法语介绍。集齐一个大区的两座城市，再奖励 ${ALBUM_BONUS} 金币。`));
  const go = el("button", "btn ghost", "去环法之旅"); go.type = "button"; go.id = "albumTour";
  go.addEventListener("click", () => switchView("tour"));
  const row = el("div", "album-buy"); row.append(go); card.append(row);
  const regDone = ALBUM_REGIONS.filter(r => albumRegionDone(r.id, owned)).length;
  const fold = foldSec("album", "城市明信片", `已收集 ${cityN} / ${ALBUM_CARDS.length} 张 · 集齐 ${regDone} / ${ALBUM_REGIONS.length} 个大区`);
  const grid = el("div", "album-grid");
  ALBUM_REGIONS.forEach(r => {
    const cs = ALBUM_CARDS.filter(c => c.r === r.id), done = cs.every(c => owned.has(c.id));
    const box = el("div", "album-reg" + (done ? " done" : ""));
    const h = el("div", "album-reg-h"); h.append(el("b", null, r.zh), el("span", null, r.fr));
    if (done) h.append(el("span", "album-stamp", "集齐"));
    box.append(h);
    const slots = el("div", "album-slots");
    cs.forEach(c => {
      if (owned.has(c.id)) {
        const b = el("button", "album-slot have"); b.type = "button"; b.id = "pc-" + c.id;
        b.append(albumArt(c), el("span", null, c.city));
        b.addEventListener("click", () => albumView(c));
        slots.append(b);
      } else {
        const b = el("div", "album-slot empty"); b.append(el("span", "pc-q", "?"), el("span", null, c.city + " · 环法解锁"));
        slots.append(b);
      }
    });
    box.append(slots); grid.append(box);
  });
  fold.append(grid);
  card.append(fold);
  // 巴黎 20 个区和大巴黎七省：只能在环法之旅里抵达后获得
  if (typeof ALBUM_PARIS !== "undefined") {
    const pn = ALBUM_PARIS.filter(c => owned.has(c.id)).length;
    const pf = foldSec("albumParis", "巴黎明信片", `已收集 ${pn} / ${ALBUM_PARIS.length} 张 · 在环法之旅的巴黎地图里抵达各区、各省获得`);
    const pg = el("div", "album-slots album-paris");
    ALBUM_PARIS.forEach(c => {
      if (owned.has(c.id)) {
        const b = el("button", "album-slot have"); b.type = "button"; b.id = "pc-" + c.id;
        b.append(albumArt(c), el("span", null, c.city.split(" · ")[0]));
        b.addEventListener("click", () => albumView(c));
        pg.append(b);
      } else {
        const b = el("div", "album-slot empty"); b.append(el("span", "pc-q", c.city.split(" · ")[0]), el("span", null, "环法解锁"));
        pg.append(b);
      }
    });
    pf.append(pg);
    card.append(pf);
  }
  if(typeof dlcAlbum === "function")dlcAlbum(card);
  return card;
}
