const tourOralLatest=id=>gameRaw.filter(g=>g.kind==='tour-oral'&&g.city===id&&(!g.scope||g.scope===oralScope()||(oralScope()==='claude'&&g.scope==='device'))).sort((a,b)=>String(a.at).localeCompare(String(b.at))).pop();
function tourAudioClear(){
  if(typeof studyAudioStop==='function')studyAudioStop();
  if(typeof tts!=="undefined"&&tts)tts.cancel();
  tourMicEpoch++;clearTimeout(tourMicTimer);
  if(tourRecorder){tourRecorder.ondataavailable=null;tourRecorder.onstop=null;if(tourRecorder.state!=='inactive')try{tourRecorder.stop();}catch(e){}}
  tourRecorder=null;if(tourMic)tourMic.getTracks().forEach(t=>t.stop());tourMic=null;
  if(tourClip){URL.revokeObjectURL(tourClip);tourClip=null;}
}
function tourOralSave(status='paused'){
 if(!tourOral)return;const o=tourOral;
 const prior=tourOralLatest(o.id);
 if(prior&&prior.status===status&&prior.variant===o.variant&&prior.node===o.node&&JSON.stringify(prior.facts)===JSON.stringify(o.facts))return;
 gameAdd({kind:'tour-oral',taskId:oralTaskId(o.id),scope:oralScope(),city:o.id,variant:o.variant,node:o.node,facts:{...o.facts},status,at:new Date().toISOString()});
}
function tourOralLeave(){if(tourOral&&tourOral.node!=='result')tourOralSave();tourAudioClear();tourOral=null;}
addEventListener('pagehide',tourOralLeave);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')tourAudioClear();});
function tourOralStart(id,variant,origin=tourOral?.origin||(view==='oral'?'oral':'tour')){
 const stop=tourStop(id);if(!stop||!tourHasOral(stop)||!TOUR_ORAL_CASES.some(c=>c.id===id)||(origin!=='oral'&&!tourCanStart(id)))return false;
 tourOralLeave();tourRun=null;
 const prior=tourOralLatest(id),resume=variant===undefined&&prior&&prior.status==='paused';
 tourOral={id,origin,variant:variant??(resume?prior.variant:0),node:resume?prior.node:'request',facts:resume?{...prior.facts}:{},ready:false,hints:0};
 if(!Number.isInteger(tourOral.variant))tourOral.variant=0;
 tourOralRender();return true;
}
