function tourOralChoose(choice,name=''){
 const o=tourOral;if(!o||!o.ready)return false;
 const valid=tourOralNode().choices.find(x=>x.id===choice);if(!valid)return false;
 if(valid.set.needsName&&!name.trim())return 'name';
 tourAudioClear();Object.assign(o.facts,valid.set);delete o.facts.needsName;
 if(valid.set.needsName)o.facts.name=name.trim().slice(0,80);
 if(valid.next==='transfer'){tourOralStart(o.id,o.variant+1);return true;}
 o.node=valid.next;o.ready=false;o.hints=0;
 if(o.node==='result')tourOralSave(o.variant>0&&tourOralComplete()?'done':'review');else tourOralSave();
 return true;
}
function tourOralComplete(){
 const o=tourOral,c=tourOralCase(),f=o.facts;
 return c.hotel?!!(f.requested&&f.room&&f.price<=110&&f.name&&f.arrival===23&&f.access&&f.delivery):!!(f.requested&&f.confirmed&&(c.id==='p5'||f.asked));
}
