async function tourRecord(){
 if(typeof petStopVoice==='function')petStopVoice();
 const o=tourOral;if(!o)return;
 if(tourRecorder?.state==='recording'){tourRecorder.stop();if(tourMic)tourMic.getTracks().forEach(t=>t.stop());tourMic=null;clearTimeout(tourMicTimer);return;}
 tourAudioClear();const epoch=tourMicEpoch;
 const notice=$('tourMicNotice');
 if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){if(notice)notice.textContent=tourText('此设备无法录音；可自主开口或跳过录音后继续。','Recording unavailable; speak on your own or skip recording.','Enregistrement indisponible ; parlez librement ou passez cette étape.');return;}
 try{
  const stream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(epoch!==tourMicEpoch||tourOral!==o||!['tour','oral'].includes(view)){stream.getTracks().forEach(t=>t.stop());return;}
  tourMic=stream;const chunks=[];tourRecorder=new MediaRecorder(stream);const recorder=tourRecorder;
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
  recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());tourMic=null;clearTimeout(tourMicTimer);if(epoch!==tourMicEpoch||tourOral!==o)return;tourClip=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'audio/webm'}));tourRecorder=null;o.ready=true;tourOralRender();};
  recorder.onerror=()=>{tourAudioClear();if(tourOral===o)tourOralRender();};
  recorder.start();tourMicTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},90000);
  tourOralRender();
 }catch(e){if(epoch!==tourMicEpoch||tourOral!==o)return;tourAudioClear();if(notice)notice.textContent=tourText('未能录音。你仍可自主开口，或跳过后用选项继续。','Recording was not available. You can still speak on your own or skip and continue with options.','L’enregistrement n’est pas disponible. Vous pouvez parler librement ou passer et continuer avec les options.');}
}
