 const c=tourOralCase(),node=tourOralNode(),card=el('section','card tour-oral');
 card.append(el('span','tag',(o.origin==='oral'?tourStop(o.id).lv+' · '+tourTr(ORAL_SCENES[o.id]):tourNo(tourStop(o.id)))+' · '+tourText('口语任务','Speaking task','Mission orale')),el('h2',null,tourTr(c.task)));
