 card.append(el('b',null,c.role),el('p','tour-dialogue',node.reply));
 const listen=tourButton(tourText('再听一遍','Listen again','Réécouter'),()=>{if(typeof speak==='function')speak(node.reply,0.85,listen);},true);card.append(listen);
