  const row=el('div','actions');row.append(tourButton(tourText('回到地图','Back to map','Retour à la carte'),tourMapBack,true),tourButton(tourText('复习并换题重测','Review and try new variants','Revoir et essayer des variantes'),()=>tourStart(stop.id)));
