// Independent routes: never append to TOUR_ROUTE or alter France's 52-stop reward.
const DLC_STOP = new Map(TOUR_DLC.flatMap(w=>w.regions.map(s=>[s.id,s])));
const dlcWorld = id => TOUR_DLC.find(w=>w.id===id);
const dlcScope = () => typeof petScope==='function'?petScope():typeof syncAuth==='function'?(syncAuth()?.uid||'local'):'local';
let dlcRun=null,dlcSelected=null;
const dlcPrior=new Map();
function dlcBest(){const out={};for(const g of gameRaw)if(g?.kind==='tour-dlc'&&DLC_STOP.has(g.region)&&g.passed===true&&Number.isInteger(g.stars)&&g.stars>=1&&g.stars<=3)out[g.region]=Math.max(out[g.region]||0,g.stars);return out;}
function dlcNext(w){const best=dlcBest();return w.regions.find(s=>!best[s.id])||null;}
function dlcCanStart(id){const s=DLC_STOP.get(id);return !!s&&gameOn()&&modeOpen('tour')&&(!!dlcBest()[id]||dlcNext(dlcWorld(s.world))?.id===id);}
function dlcQuestion(row,s,role=row.role){const m=row.sentence.match(/^(.*?)\[([^\]]+)\](.*)$/);if(!m)throw Error('DLC answer missing '+row.id);return {id:row.id,stop:s.id,role,q:m[1]+'___'+m[3],answer:m[2],full:m[1]+m[2]+m[3],opts:[m[2],...row.wrong],rule:s.rule,goal:s.goal,verb:row.verb};}
function dlcQuestions(s,rng=Math.random){
 const w=dlcWorld(s.world), prior=w.regions[Math.max(0,s.no-2)],used=dlcPrior.get(dlcScope()+':'+s.id)||new Set();
 const targets=s.questions.filter(q=>q.role==='target').map(q=>dlcQuestion(q,s));
 const chosen=tourTake(targets,4,used,rng);
 const review=prior.questions.filter(q=>q.role==='target').map(q=>dlcQuestion(q,prior,'review')).filter(q=>!chosen.some(x=>x.id===q.id));
 chosen.push(...tourTake(review,2,used,rng),...tourTake(s.questions.filter(q=>q.role==='scene').map(q=>dlcQuestion(q,s)),2,used,rng));
 if(chosen.length!==8||new Set(chosen.map(q=>q.id)).size!==8)throw Error('Invalid DLC round '+s.id);
 dlcPrior.set(dlcScope()+':'+s.id,new Set(chosen.map(q=>q.id)));
 return chosen.map(q=>({...q,opts:tourShuffle(q.opts,rng)}));
}
// Register stable IDs for progress, wrong-answer review and daily plans.
for(const w of TOUR_DLC)ROUND_NAMES["dlc-"+w.id]=tourTr(w.name);
for(const w of TOUR_DLC)for(const s of w.regions){
 const kp='dlc-'+s.id;
 KP[kp]={t:tourTr(s.goal),b:tourTr(s.rule)};ROUND_NAMES[kp]=tourTr(w.name)+' · '+s.name;
 for(const row of s.questions){const q=dlcQuestion(row,s),tags=[w.id==='qc'?'直陈式现在时':'旅行语法','法语区旅行'];
  const item={id:q.id,ch:0,cat:tourTr(s.goal),q:q.q,opts:q.opts,a:0,exp:tourTr(q.rule),kp,level:s.level,tags};
  if(!BY_ID.has(q.id)){BANK.push(item);BY_ID.set(q.id,item);}LEVEL_OF[q.id]=s.level;TAGS_OF[q.id]=tags;
 }
}
