function dlcRegionCardId(id){return 'dlc-region-card-'+id;}
// Append only missing cards; historical learning records and coins are never rewritten.
function dlcRestoreRegionCards(){const best=dlcBest(),owned=gameLedger().cards;let count=0;for(const id of Object.keys(best)){const key=dlcRegionCardId(id);if(!owned.has(key)){gameAdd({kind:'card',id:key,price:0,at:new Date().toISOString()});owned.add(key);count++;}}return count;}
