const fbText = key => (FB_COPY[typeof UI_LANG === "undefined" ? "zh" : UI_LANG] || FB_COPY.zh)[key];
let fbEpoch = 0;
const fbPictures = new Set();
const fbUid = () => SYNC_ON ? syncAuth()?.uid || "" : "";
function fbCurrent(uid, epoch) { return fbEpoch === epoch && fbUid() === uid; }
async function fbRpc(name, args = {}, publicRead = false) {
  const uid = fbUid(), epoch = fbEpoch;
  const controller = new AbortController(), timer = setTimeout(() => controller.abort(), 12000);
  try {
    const data = await syncFetch("/rest/v1/rpc/" + name, { method: "POST", body: JSON.stringify(args), signal: controller.signal }, !!uid || !publicRead, uid);
    if (!fbCurrent(uid, epoch)) { const err = new Error("Account changed"); err.code = "account"; throw err; }
    return data;
  } finally { clearTimeout(timer); }
}
function fbButton(text, cls = "btn ghost") { const b = el("button", cls, text); b.type = "button"; return b; }
function fbLoginLink() {
  const b = fbButton(fbText("loginGo"), "fb-link");
  b.addEventListener("click", () => tabSet.click()); return b;
}
function feedbackOnAccountChange() {
  fbEpoch++;
  studyStatsRun++;studyCounts.clear();studySort={q:"normal",w:"normal"};
  document.querySelectorAll(".avatar-settings").forEach(n=>n.remove());
  // Remove private information synchronously, before another request can finish.
  document.querySelectorAll(".fb-admin,.fb-private,.fb-public").forEach(n => n.remove());
  fbPictures.forEach(item => { if (!item.root.isConnected) fbPictures.delete(item); else item.reload(); });
  if (typeof view !== "undefined" && view === "settings") renderSettings();
}
function fbSaveReward(reward, uid) {
  if (!uid || fbUid() !== uid || !reward || reward.kind !== "feedback_reward" || reward.scope !== "user:" + uid || reward.key !== "feedback:first" || reward.coins !== 800) return;
  // Save the server-issued record locally without uploading it back as a client-created reward.
  const list = syncLocal("game").filter(g => !(g.kind === "feedback_reward" && g.scope === reward.scope));
  list.push(reward); syncStore("game", list);
  if (typeof gameRaw !== "undefined") {
    gameRaw = gameRaw.filter(g => !(g.kind === "feedback_reward" && g.scope === reward.scope));
    gameRaw.push(reward);
  }
  if (typeof planRefresh === "function") planRefresh();
  if (typeof socPushSoon === "function") socPushSoon();
}

