let shareLastImage = '';
function sharePickImage(random = Math.random) {
 let last=shareLastImage;try {last=localStorage.getItem('fq-share-last-image')||last;}catch(e){}
 const candidates=SHARE_IMAGES.filter(x=>x.id!==last),pool=candidates.length?candidates:SHARE_IMAGES;
 const picked=pool[Math.min(pool.length-1,Math.max(0,Math.floor(random()*pool.length)))];
 shareLastImage=picked.id;try{localStorage.setItem('fq-share-last-image',picked.id);}catch(e){}
 return picked;
}
