const shareText = k => (SHARE_I18N[typeof UI_LANG === 'string' ? UI_LANG : 'zh'] || SHARE_I18N.zh)[k];
const shareUid = () => typeof SYNC_ON !== 'undefined' && SYNC_ON && typeof syncAuth === 'function' ? syncAuth()?.uid || '' : '';
// Only requested posters are loaded; reuse a selected file without preloading the gallery.
const shareFiles = new Map();
function shareFile(image) {
 const url='../skins/share/'+image.file;
 if(!shareFiles.has(url)) {
  const pending=(async()=>{
   const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),15000);
   try {const r=await fetch(url,{signal:ac.signal});if(!r.ok)throw Error('image');const blob=await r.blob();return new File([blob],image.file,{type:'image/jpeg'});}
   finally {clearTimeout(timer);}
  })().catch(e=>{shareFiles.delete(url);throw e;});
  shareFiles.set(url,pending);
 }
 return shareFiles.get(url);
}
async function shareRpc(name, data, uid) {
 const ac=new AbortController(), timer=setTimeout(()=>ac.abort(),15000);
 try {return await syncFetch('/rest/v1/rpc/'+name,{method:'POST',body:JSON.stringify(data),signal:ac.signal},true,uid);}
 finally {clearTimeout(timer);}
}
function shareSaveReward(r,uid) {
 if(!uid||shareUid()!==uid||!r||r.kind!=='share_reward'||r.key!=='share:first'||r.scope!=='user:'+uid||r.coins!==800)return false;
 const merge=rows=>[...rows.filter(g=>!(g.kind==='share_reward'&&g.scope===r.scope)),r];
 syncStore('game',merge(syncLocal('game')));
 if(typeof gameRaw!=='undefined')gameRaw=merge(gameRaw);
 if(typeof planRefresh==='function')planRefresh();
 if(typeof socPushSoon==='function')socPushSoon();
 return true;
}
