 vowel:['元音组合','Vowel spellings','Graphies vocaliques'],nasal:['鼻元音','Nasal vowels','Voyelles nasales'],glide:['半元音','Glides','Semi-voyelles'],consonant:['辅音组合','Consonant spellings','Graphies consonantiques'],ending:['词尾发音','Word endings','Finales'],
 liaison:['联诵 · liaison','Liaison','Liaison'],elision:['省音 · élision','Elision','Élision'],enchainement:['连读 · enchaînement','Enchaînement','Enchaînement'],hiatus:['元音相遇 · hiatus','Hiatus','Hiatus'],alphabet:['字母名称','Letter names','Noms des lettres']
