function phoneticText(v){return v[UI_LANG==='fr'?2:UI_LANG==='en'?1:0];}
function phoneticLabel(k){return PHONETIC_LABELS[k]?phoneticText(PHONETIC_LABELS[k]):k;}
function phoneticRegister(){
 const add=q=>{q.ch=0;q.r=0;q.level='A1';q.listeningSource='phonetics';q.cat='听力 · 语音基础';q.tags=[phoneticLabel(q.listeningKind),phoneticLabel(q.listeningTopic)];q.a=0;q.phonetic=true;BANK.push(q);BY_ID.set(q.id,q);};
 const letters=PHONETICS_DATA.alphabet,groups=['BDPTV','CGJ','EFLSMN','AIYU','HKQR','OWXZ'];
 for(const [letter,ipa,name] of letters){
  const nearby=groups.find(g=>g.includes(letter))||'';
  const others=[...nearby,...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].filter((x,i,a)=>x!==letter&&a.indexOf(x)===i).slice(0,3);
  const choices=[letter,...others].map(l=>letters.find(x=>x[0]===l));
  const exp=phoneticText([`字母 ${letter} 的名称读 /${ipa}/，这不等于它在单词中的所有读法。`,`The name of ${letter} is /${ipa}/; its sounds in words may differ.`,`Le nom de ${letter} se prononce /${ipa}/ ; ses sons dans les mots peuvent différer.`])+(letter==='E'?phoneticText([' E 的传统音标写 /ə/，单独念字母时也常接近 [ø]。',' E is traditionally transcribed /ə/; its isolated name often approaches [ø].',' E est traditionnellement transcrit /ə/ ; son nom isolé se rapproche souvent de [ø].']):'');
  const common={listeningKind:'letter',listeningTopic:'alphabet',audio:name,quote:letter+' /'+ipa+'/',exp};
  add({...common,id:'phon-letter-'+letter.toLowerCase()+'-ipa',listeningMode:'letter-ipa',hidePromptAudio:true,q:phoneticText([`字母 ${letter} 的名称对应哪个 IPA 音标？`,`Which IPA transcription names the letter ${letter}?`,`Quelle transcription API donne le nom de la lettre ${letter} ?`]),opts:choices.map(x=>'/'+x[1]+'/')});
  add({...common,id:'phon-letter-'+letter.toLowerCase()+'-hear',listeningMode:'letter-hear',q:phoneticText(['听读音，选择字母。','Listen and choose the letter.','Écoutez et choisissez la lettre.']),opts:choices.map(x=>x[0])});
  add({...common,id:'phon-letter-'+letter.toLowerCase()+'-sound',listeningMode:'letter-sound',hidePromptAudio:true,audioOptions:choices.map(x=>x[2]),q:phoneticText([`哪段读音是字母 ${letter} 的名称？`,`Which sound names the letter ${letter}?`,`Quel son donne le nom de la lettre ${letter} ?`]),opts:choices.map(x=>x[0])});
 }
 PHONETICS_DATA.rules.forEach(([topic,spelling,word,ipa,wrong,...explanation],i)=>add({id:'phon-spelling-'+String(i+1).padStart(3,'0'),listeningKind:'syllable',listeningTopic:topic,listeningMode:'phonics',audio:word,quote:word+' · '+spelling+' /'+ipa+'/',q:phoneticText([`「${word}」中的「${spelling}」读什么音？`,`How is “${spelling}” pronounced in “${word}”?`,`Comment se prononce « ${spelling} » dans « ${word} » ?`]),opts:[ipa,...wrong.split('|')].map(x=>x==='∅'?phoneticText(['不发音','Silent','Muet']):'/'+x+'/'),exp:phoneticText(explanation)}));
 PHONETICS_DATA.phenomena.forEach(([topic,phrase,correct,wrong,...explanation],i)=>{
  const prompt=topic==='elision'?['选择这段表达的省音变化。','Choose the elision in this expression.','Choisissez l’élision dans cette expression.']:topic==='hiatus'?['这段表达中相遇的元音怎样发音？','How are the adjacent vowels pronounced here?','Comment se prononcent les voyelles en contact ?']:['这段表达在词与词之间连接的辅音是什么？','Which consonant links the words here?','Quelle consonne relie les mots ici ?'];
  const opt=x=>topic==='elision'?(x==='不省音'?phoneticText(['不省音','No elision','Pas d’élision']):x):x==='∅'?phoneticText(['没有连接辅音','No linking consonant','Aucune consonne de liaison']):'/'+x+'/';
  add({id:'phon-connected-'+String(i+1).padStart(3,'0'),listeningKind:'phenomenon',listeningTopic:topic,listeningMode:'phonics',audio:phrase,quote:phrase,q:phrase+' — '+phoneticText(prompt),opts:[correct,...wrong.split('|')].map(opt),exp:phoneticText(explanation)});
 });
}
