function listeningMaterialKind(text){
 text=text.replace(/\b(M|Mme|Mlle|Dr|Pr)\.(?=\s+\p{Lu})/gu,'$1');
 const segments=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter('fr',{granularity:'sentence'}).segment(text),x=>x.segment.trim()).filter(Boolean):listeningSentenceRanges(text);
 return segments.length>1||/(?:^|\n)\s*[—–-]\s|(?:^|\n)\s*(?:[A-Z][\p{L} ]{0,24}|[AB])\s*:/u.test(text)?'passage':'sentence';
}
function listeningRegister(){
 const seen=new Set(),extra=[];
 BANK.forEach(q=>{
  if(!q.audio||!LISTENING_GAPS[q.audio])return;
  q.listeningKind=q.listeningKind||listeningMaterialKind(q.audio);
  q.listeningMode='comprehension';q.listeningSource=q.listeningSource||'general';q.listeningTopic=q.listeningTopic||q.cat.replace(/^(听力|长文|听写辨音)\s*[·：:]\s*/, '');
  if(seen.has(q.audio))return;seen.add(q.audio);
  for(const mode of ['cloze','order']){
   const sentences=mode==='order'?listeningSentences(q.audio):[null];
   sentences.forEach((sentence,index)=>{
    if(mode==='order'&&q.listeningOrderMin&&listeningWords(sentence).length<q.listeningOrderMin)return; // 对话里的短句不出排序题；编号仍按原句序
    const correct=mode==='cloze'?LISTENING_GAPS[q.audio].map(g=>g.options[0]).join(' / '):sentence;
    const item={...q,id:q.id+'-'+mode+(index?'-'+(index+1):''),sourceId:q.id,listeningMode:mode,listeningSentence:index,q:LISTEN_LABELS[mode][0],a:0,opts:[correct,'—'],hint:'',exp:mode==='order'?sentence:q.audio};
    extra.push(item);BY_ID.set(item.id,item);
   });
  }
 });
 BANK.push(...extra);
}
