// Keep pending directory choices separate for grammar and listening.
let pendingQuizTagKey = null;
let pendingListeningKey = null;
const quizPendingKey = () => qBoard === "listen" ? pendingListeningKey : pendingQuizTagKey;
function refreshPendingQuiz() {
  if (qIntro) renderBoardIntro();
  else if (stage.querySelector(".review")) renderResult();
}
function queueQuizTags() {
  if (qBoard !== "grammar") return;
  const key = pickTags.size || tagRandom ? tagKey("tag") : null;
  pendingQuizTagKey = key && key !== set?.key ? key : null;
  refreshPendingQuiz();
}
function queueListeningFilters(f) {
  if (view !== "quiz" || qBoard !== "listen") return;
  const key = listeningKey(f);
  pendingListeningKey = key !== set?.key ? key : null;
  refreshPendingQuiz();
}
function nextQuizBatch(from) {
  const key = quizPendingKey();
  if (key) startSet(key, true);
  else if(set && (parseTagKey(set.key)?.tags.some(t=>ATTEMPT_TAGS.includes(t)) || set.key.startsWith("listen:") && listeningFilter(set.key).attempts.length)) startSet(set.key,true);
  else startBatch(from);
}

