// 理解选择题（单词例句）和“听句选译文”（所有单句材料）：内容在 listening-extra.js，由 tools/listening-extra/build.py 生成。
// 每条：[中文译文, 3 个中文干扰项, 英文译文, 3 个英文干扰项, 法语问题, 4 个法语选项]（后两项只有单词例句有）。
// 译文题只在中文和英文界面出：中文界面选中文译文，英文界面选英文译文；法语界面不出。
// 朗读单词用的文本，和背单词页面的 vArt 一致（名词带冠词）；这里单独写一份，因为 pictures.js 在后面才加载
function vocabListeningArticle(w){
 if(!w.pos.startsWith('n'))return w.fr;
 if(w.pos==='nfpl'||w.pos==='nmpl')return 'les '+w.fr;
 if(/^[aeiouyàâéèêëîïôöùûœh]/i.test(w.fr)&&!V_HASPIRE.has(w.fr))return "l'"+w.fr;
 return (w.pos==='nm'?'le ':'la ')+w.fr;
}
function listeningExtraRegister(){
 if(typeof LISTENING_EXTRA==='undefined')return;
 const lang=UI_LANG==='fr'?2:UI_LANG==='en'?1:0,items=[];
 const translate=(base,id,x)=>{
  if(lang===2)return;
  const right=lang?x[2]:x[0],wrong=lang?x[3]:x[1];
  items.push({...base,id:id+'-translate',sourceId:id,listeningMode:'translate',listeningSentence:0,q:lang?'Listen to the sentence and choose the correct translation.':'听句子，选出正确的译文。',opts:[right,...wrong],a:0,hint:'',exp:(lang?'Translation: ':'译文：')+right});   // 原句会在答完后自动显示，这里只补上正确译文
 };
 for(const q of BANK.slice()){
  if(q.listeningSource==='vocabulary'&&q.listeningMode==='cloze'){
   const x=LISTENING_EXTRA[q.sourceId];if(!x)continue;
   const {listeningMode,sourceId,...base}=q;
   if(x[4]){const answer=x[5][0],meaning=lang===1?x[2]:lang===2?'':x[0];
    const exp=lang===0?'正确答案：'+answer+'。译文：'+meaning:lang===1?'Answer: '+answer+'. Translation: '+meaning:'Réponse : '+answer+'.';
    items.push({...base,id:sourceId,listeningMode:'comprehension',q:x[4],opts:x[5].slice(),a:0,exp});}
   translate(base,sourceId,x);
  }else if(q.listeningMode==='comprehension'&&!q.phonetic&&LISTENING_EXTRA[q.id]){
   translate(q,q.id,LISTENING_EXTRA[q.id]);
  }
 }
 // 听写（键盘输入）：只给短材料出——有译文的单句，以及单词本身。译文按界面语言显示，法语界面不显示译文。
 const prompt=x=>lang===2?'':lang?x[2]:x[0],seenAudio=new Set();
 for(const q of BANK.slice()){
  const id=q.listeningSource==='vocabulary'&&q.listeningMode==='cloze'?q.sourceId:q.listeningMode==='comprehension'&&!q.phonetic&&q.listeningSource!=='vocabulary'?q.id:null,x=id&&LISTENING_EXTRA[id];
  if(!x||seenAudio.has(q.audio))continue;seenAudio.add(q.audio);
  const {listeningMode,sourceId,...base}=q;
  items.push({...base,id:id+'-dictation',sourceId:id,listeningMode:'dictation',listeningSentence:0,q:LISTEN_LABELS.dictation[0],opts:[q.audio,'—'],a:0,hint:'',exp:q.audio,prompt:prompt(x)});
 }
 const themes=new Map(VOCAB.map(t=>[t.id,t.t])),zhOf=w=>w.zh||(typeof V_ZH!=='undefined'&&V_ZH[w.fr])||w.en,heard=new Set();
 for(const w of V_WORDS){
  const audio=vocabListeningArticle(w);if(heard.has(audio)||LISTENING_GAPS[audio])continue;heard.add(audio);
  LISTENING_GAPS[audio]=[];   // 让它被当成听力材料；单词没有填空
  const functional=w.id.startsWith('fw-'),level=functional?'A1':'B1',topic=themes.get(w.th)||'单词例句';
  items.push({id:'fr-vw-'+w.id+'-dictation',sourceId:'fr-vw-'+w.id,ch:0,r:0,cat:'听力 · 单词',level,tags:[level,topic,'单词'],audio,a:0,hint:'',listeningKind:'word',listeningSource:'vocabulary',listeningTopic:topic,listeningMode:'dictation',listeningSentence:0,
   q:LISTEN_LABELS.dictation[0],opts:[w.fr,'—'],exp:audio,accept:[w.fr,audio],prompt:lang===2?'':lang?w.en:zhOf(w),vocabWord:w.id});
 }
 const seen=new Set();
 for(const q of items){if(BY_ID.has(q.id)||seen.has(q.id))continue;seen.add(q.id);BANK.push(q);BY_ID.set(q.id,q);}
}
