  card.append(stats);
  const row = el("div", "v-start");
  const lab = el("label", "per");
  const sel = el("select"); sel.id = "vPerSel";
  [5, 10, 15, 20].forEach(k => sel.append(new Option(String(k), String(k))));
  sel.value = String(vPer);
  const goLabel = () => `开始练习（${isLv ? words.length : Math.min(vPer, words.length)} 个词）`;
  const go = el("button", "btn", goLabel()); go.type = "button"; go.id = "vGo";
  sel.addEventListener("change", () => { vPer = Number(sel.value); try { localStorage.setItem("fq-vper", String(vPer)); } catch (e) {} go.textContent = goLabel(); });
