  const r = vLvRemote(p.lv);
  if (r && Date.parse(r.at) >= p.x.at) { vLvPending = null; return; }
  gameAdd({ kind: "vlv", lv: p.lv, ...p.x, at: new Date(p.x.at).toISOString() });
