addEventListener("pagehide", vLvFlush);
document.addEventListener("visibilitychange", () => { if (document.visibilityState === "hidden") vLvFlush(); });
function vLvClear(k) {
  const all = vLvAll(), r = vLvRemote(k);
  const at = Math.max(Date.now(), Number(all[k]?.at) + 1 || 0, (Date.parse(r?.at) || 0) + 1);
  all[k] = { clear: true, at };
  try { localStorage.setItem("fq-vlv", JSON.stringify(all)); } catch (e) {}
  if (vLvPending && vLvPending.lv === k) { vLvPending = null; clearTimeout(vLvTimer); }
  if (typeof gameAdd === "function" && dbRef) gameAdd({ kind: "vlv", lv: k, clear: true, at: new Date(at).toISOString() });
}
// 云端（同步过来的 game 记录）里这一关最新的一份
function vLvRemote(k) {
  if (typeof gameRaw === "undefined") return null;
  let best = null;
  gameRaw.forEach(g => { if (g.kind === "vlv" && g.lv === k && (!best || String(g.at) > String(best.at))) best = g; });
  return best;
}
// Recover checkpoints left only in fq-vlv by older versions or a page closed before database startup.
