    if (!Number.isInteger(lv) || lv < 0 || lv >= V_LEVELS.length || !Number.isFinite(at) || at <= 0 || at > 8640000000000000) continue;
    if (!x.clear && (!Array.isArray(x.words) || !Array.isArray(x.qs) || !Number.isInteger(x.i) || x.i <= 0)) continue;
