  const take = () => { const got = spGain(id); spReward("宝箱打开了", ["遗物：" + got + (id ? ` · ${SP_RELICS[id].desc}` : "")]); };
  if (spKeys().blue) { take(); return; }
  // 还没拿蓝钥匙：遗物和蓝钥匙二选一
