function spShop() {
  const r = spRun;
  if (!r.shop || r.shop.at !== r.row + ":" + r.col) r.shop = { at: r.row + ":" + r.col, items: vShuffle(spFreeRelics()).slice(0, 3), sold: [], pots: [spRollPotion(), spRollPotion()], potSold: [] };
  if (!r.shop.pots) { r.shop.pots = [spRollPotion(), spRollPotion()]; r.shop.potSold = []; }
  if (r.shopHalf && r.shop.half === undefined) { r.shop.half = true; r.shopHalf = false; }
  const off = (spHas("macaron") ? .75 : 1) * (r.shop.half ? .5 : 1), price = k => Math.round([130, 160, 190][k] * off), heal = Math.round(30 * off);
  const draw = () => {
    const ch = r.shop.items.map((id, k) => [`${SP_RELICS[id].name} · ${price(k)} 金币`, SP_RELICS[id].desc,
      () => { r.gold -= price(k); r.shop.sold.push(id); spGain(id); spSave(); draw(); }, r.shop.sold.includes(id) || r.gold < price(k)]);
    const pprice = id => Math.round(SP_POTIONS[id].price * off), full = spPots().length >= spSlots();
    r.shop.pots.forEach((id, k) => ch.push([`药水 · ${SP_POTIONS[id].name} · ${pprice(id)} 金币`, SP_POTIONS[id].desc + (full ? "（药水栏满了）" : ""),
      () => { r.gold -= pprice(id); r.shop.potSold.push(k); spGetPotion(id); spSave(); draw(); }, r.shop.potSold.includes(k) || r.gold < pprice(id) || full]));
    ch.push([`补 1 颗心 · ${heal} 金币`, `现在 ${r.hp} / ${r.max}`, () => { r.gold -= heal; spHeal(1); draw(); }, r.gold < heal || r.hp >= r.max]);
    ch.push(["离开", "", spDone]);
    const card = spRoom("商人 · Le Marchand", "shop", `你有 ${r.gold} 金币。`, ch, "../skins/spire/ev-shop.webp");
    card.querySelectorAll(".sp-choice").forEach((b, k) => { const n = r.shop.items.length; if (k < n) b.prepend(spIcon("relic", r.shop.items[k])); else if (k < n + r.shop.pots.length) b.prepend(spIcon("potion", r.shop.pots[k - n])); });
  };
  spSave(); draw();
}
