let cafeModel=null,cafeCache=null,cafePanel='tools',cafeRecipe='espresso';
try{cafeRecipe=localStorage.getItem('fq-cafe-recipe')||cafeRecipe;}catch(e){}
function cafeRead(now=Date.now()){
 if(!cafeModel)cafeModel=CafeEngine.create(CafeData,TAG_GROUPS,BANK,CJ_VERBS);
 if(!gameLoaded||!Array.isArray(ansRaw))return null;
 const at=now;
 if(cafeCache&&cafeCache.at===at&&cafeCache.g===gameRaw&&cafeCache.a===ansRaw&&cafeCache.v===vocRaw&&cafeCache.gn===gameRaw.length&&cafeCache.an===ansRaw.length&&cafeCache.vn===vocRaw.length)return cafeCache.state;
 const state=cafeModel.replay({game:gameRaw,answers:ansRaw,vocab:vocRaw},at);
 cafeCache={at,g:gameRaw,a:ansRaw,v:vocRaw,gn:gameRaw.length,an:ansRaw.length,vn:vocRaw.length,state};return state;
}
function cafeAdd(kind,fields={}){
 if(!gameOn()||!gameLoaded||!dbRef){xpToast('咖啡馆暂时无法保存，请稍后重试');return;}
 const state=cafeRead();
 if(kind==='idle-shift'&&(!state||!state.machines.some(m=>m.tag===fields.tag&&m.open&&m.active&&m.paid<m.cap&&state.tips>=m.price)))return;
 if(kind==='idle-branch'&&!state?.canBranch)return;
 const eid=globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
 gameAdd({kind,eid,v:CafeData.version,at:new Date().toISOString(),...fields});cafeCache=null;
}
function cafeVisit(){
 let s=cafeRead();if(!s?.started)return s;
 const day=dayKey(new Date());if(!s.visits.has(day)){cafeAdd('idle-visit',{day});s=cafeRead();}return s;
}
function cafePractice(tag,review=false){
 cafeMarkAway();
 const key=(review?'rev:':'learn:')+tag;
 if(!progMembers(key).length){
  const tenses=Object.entries(CafeData.tenses).filter(([,v])=>v===tag).map(([k])=>k);
  if(tenses.length){cjCfg.tenses=tenses;cjSaveCfg();goBoard('conj');return;}
  if(review){xpToast('现在没有到期要复习的题');return;}
 }
 qBoard='grammar';qIntro=false;progGo(key);
}
function cafeMarkAway(){
 if(typeof view==='undefined'||view!=='cafe')return;
 try{localStorage.setItem('fq-cafe-away',String(Date.now()));}catch(e){}
}
function cafeOffline(s){
 let away=0;try{away=Number(localStorage.getItem('fq-cafe-away'));localStorage.removeItem('fq-cafe-away');}catch(e){}
 const now=Date.now();if(!away||now-away<5*60000||away<s.start||away>now)return;
 const before=cafeRead(away);if(!before)return;
 cafeDialog('欢迎回到河畔咖啡馆',[
  cafeSay('离开 ${hours} 小时，实际营业 ${minutes} 分钟。',{hours:((now-away)/3600000).toFixed(1),minutes:Math.max(0,s.servedMinutes-before.servedMinutes).toFixed(0)}),
  cafeSay('自动获得 ${tips} 小费，已经计入余额。',{tips:cafeNumber(Math.max(0,s.autoTotal-before.autoTotal))}),
  '营业时间用完后会打烊；做题后可继续营业。'
 ]);
}
