// ---------- 学习伙伴：配置、学习里程碑和已有金币账本 ----------
const PET_PRICES = { pet: 800, "pet-bookmark": 150, "pet-hairpin": 300, "pet-cape": 500 };
const PET_TIERS = [0, 30, 100, 300, 600];
