  const result={};
  for(const c of Object.keys(points))result[c]={points:points[c],max:2400,today:td[c],dailyCap:24,totalToday:td.total,totalDailyCap:48,level:PET_TIERS.filter(n=>points[c]>=n).length-1,nextReset:new Date(Date.parse(today+'T00:00:00.000Z')+DAY_MS).toISOString(),lastGain:lastGain[c]||null,nextReward:PET_REWARD_STEPS.find(n=>n>points[c])||null};
