  if(!tts){done?.();return false;}const v=exVoices(),u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';if(v[role])u.voice=v[role];u.rate=rate;u.pitch=v.F===v.M?(role==='F'?1.15:.85):1;u.onend=u.onerror=()=>{btn?.setAttribute('aria-pressed','false');done?.();};tts.speak(u);btn?.setAttribute('aria-pressed','true');return true;
