  const epoch=studyAudioEpoch,voice=voiceOverride||studyVoice();let i=0,partEpoch=0;studyAudioBusy=true;btn?.setAttribute('aria-pressed','true');
  const row=btn?.parentElement?.classList.contains('study-player')?btn.parentElement:null;
  const s=studyAudioSession={row,rate:row?studyAudioRate():rate,paused:false,loop:!!row&&studyAudioLoop,index:0,partIndex:0,partCount:parts.length,segments:null,mode:'loading',ended:false,timer:null};studyControlsSync(s);
