  // are detected with performance.now by the runtime before calling this function.
  if(s.run?.status==='running' && now<s.run.updated-2000) {pomoPause(s,s.run.updated,'clock');return;}
  if(s.run?.status==='running' && now>=s.run.deadline)pomoFinish(s,now);
  if(action==='tick')return;
  if(action==='config') {s.config=pomoConfig({...s.config,...patch});return;}
  if(action==='pause'){pomoPause(s,now);return;}
  if(action==='resume' && s.run?.status==='paused') {s.run.status='running';s.run.deadline=now+s.run.remaining;s.run.updated=now;s.warning='';return;}
  if(action==='abort'){pomoFinish(s,now,'aborted');return;}
