  if(pomoHasCompanion()){
    petSetState(s.run.phase==='focus'?'happy':'idle');
    if(!petBlocked()){const line=pomoLine(s);petRuntime.line={fr:line[0],zh:line[1],en:line[2]};petRuntime.open=true;petRuntime.manual=false;petRenderBubble();petRefresh();clearTimeout(petBubbleTimer);petBubbleTimer=setTimeout(()=>petCloseBubble(),6500);}
  }
  if(s.config.sound && (!petOwned() || petConfig().voice))pomoChime();
