    button.querySelector('.pomo-companion-title').textContent=pomoText('title');
    button.title=pomoText('config');clock.hidden=!active;phase.hidden=!active;
    phase.textContent=active?pomoText(r.phase)+' · '+pomoText(r.status):'';
