  pomoCompanionDraw();
  const announce=[r?.id,status].join(':');if(announce!==pomoLastAnnounce){pomoLastAnnounce=announce;const label=$('pomoStatus');if(label)label.textContent=pomoText(phase)+' · '+pomoText(status);}
