// First-party, account-scoped visible-page duration. Never records input, URLs or audio.
const USAGE_PREFIX='fq-usage-outbox:', USAGE_MAX_AGE=7*86400000;
let usageUid='',usageLast=Date.now(),usageVisible=false,usageBusy=false,usageTicks=0;
const usagePending=new Map(),usagePreferences=new Map();
const usageAccount=()=>SYNC_ON?syncAuth()?.uid||'':'';
function usageEnabled(uid=usageAccount()){if(!uid)return false;if(usagePreferences.has(uid))return usagePreferences.get(uid);try{return localStorage.getItem('fq-usage-enabled:'+uid)!=='0';}catch(e){return true;}}
function usageMerge(map,minute,mask){try{const n=BigInt(mask);if(n>0n&&n<(1n<<60n))map.set(minute,(map.get(minute)||0n)|n);}catch(e){}}
function usageMark(map,start,end){
 if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return;
 // A delayed/suspended timer is not evidence that the entire gap was viewed.
 start=Math.max(start,end-15000);
 for(let second=Math.floor(start/1000);second<Math.floor(end/1000);second++){
  const minute=new Date(Math.floor(second/60)*60000).toISOString();
  usageMerge(map,minute,1n<<BigInt(second%60));
 }
}
function usageCollect(now=Date.now()){
 if(usageUid&&usageVisible)usageMark(usagePending,usageLast,now);
 usageLast=now;
}
function usageRows(map){return [...map].sort(([a],[b])=>a.localeCompare(b)).map(([minute,mask])=>({minute,mask:String(mask)}));}
function usagePersist(){
 if(!usageUid||!usagePending.size)return;
 try{
  const key=USAGE_PREFIX+usageUid+':'+crypto.randomUUID();
  localStorage.setItem(key,JSON.stringify({at:Date.now(),minutes:usageRows(usagePending)}));usagePending.clear();
 }catch(e){} // Storage failure keeps the unsent seconds in memory.
}
function usageOutbox(uid){
 const found=[],prefix=USAGE_PREFIX+uid+':';
 try{
  const keys=Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).filter(k=>k?.startsWith(prefix));
  for(const key of keys){
   let data;try{data=JSON.parse(localStorage.getItem(key));}catch(e){}
   if(!data||!Number.isFinite(data.at)||data.at<Date.now()-USAGE_MAX_AGE||!Array.isArray(data.minutes)){localStorage.removeItem(key);continue;}
   found.push({key,...data});
  }
  found.sort((a,b)=>a.at-b.at);
  // Bound only this feature's retry cache. Never touch answers, coins or login data.
  while(found.length>4000)localStorage.removeItem(found.shift().key);
 }catch(e){}
 return found;
}
async function usageFlush(){
 if(usageBusy||!usageUid||usageAccount()!==usageUid||navigator.onLine===false)return;
 const uid=usageUid;usagePersist();const batches=usageOutbox(uid).slice(0,50),snapshot=new Map(usagePending),merged=new Map(snapshot);
 for(const b of batches)for(const row of b.minutes){const t=Date.parse(row.minute);if(Number.isFinite(t)&&t>=Date.now()-USAGE_MAX_AGE+60000&&t<=Date.now())usageMerge(merged,new Date(Math.floor(t/60000)*60000).toISOString(),row.mask);}
 const rows=usageRows(merged);if(!rows.length){for(const b of batches)try{localStorage.removeItem(b.key);}catch(e){}return;}
 usageBusy=true;
 try{
  // Outbox chunks are immutable; concurrent tabs may safely retry the same seconds.
  for(let i=0;i<rows.length;i+=120){
   const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),12000);
   try{await syncFetch('/rest/v1/rpc/record_visible_usage',{method:'POST',body:JSON.stringify({p_minutes:rows.slice(i,i+120)}),signal:ac.signal,keepalive:true},true,uid);}
   finally{clearTimeout(timer);}
  }
  for(const b of batches)try{localStorage.removeItem(b.key);}catch(e){}
  if(usageUid===uid)for(const [minute,mask]of snapshot){const rest=(usagePending.get(minute)||0n)&~mask;if(rest)usagePending.set(minute,rest);else usagePending.delete(minute);}
 }catch(e){} // Best effort. The next heartbeat/visit retries without duplicating time.
 finally{usageBusy=false;}
}
function usageAccountChanged(){
 usageCollect();usagePersist();usagePending.clear();usageUid=usageAccount();usageLast=Date.now();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';void usageFlush();
}
function usageVisibility(){usageCollect();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';usagePersist();void usageFlush();}
function usageSetEnabled(enabled){
 const uid=usageAccount();if(!uid)return;usageCollect();usagePersist();
 usagePreferences.set(uid,enabled);try{localStorage.setItem('fq-usage-enabled:'+uid,enabled?'1':'0');}catch(e){}
 usageVisible=enabled&&document.visibilityState==='visible';usageLast=Date.now();void usageFlush();
}
function usageInit(){
 if(!SYNC_ON)return;usageAccountChanged();
 setInterval(()=>{if(usageAccount()!==usageUid){usageAccountChanged();return;}usageCollect();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';if(++usageTicks%6===0)void usageFlush();},5000);
 document.addEventListener('visibilitychange',usageVisibility);
 addEventListener('pagehide',()=>{usageCollect();usageVisible=false;usagePersist();void usageFlush();});
 addEventListener('pageshow',()=>{usageLast=Date.now();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';void usageFlush();});
 addEventListener('online',()=>void usageFlush());
 addEventListener('storage',e=>{if(e.key==='fq-usage-enabled:'+usageUid){usagePreferences.delete(usageUid);usageVisibility();}});
}
queueMicrotask(usageInit);
queueMicrotask(()=>{if(typeof funnelStep==='function')funnelStep('open');});

const usageText=(zh,en,fr)=>typeof UI_LANG==='undefined'||UI_LANG==='zh'?zh:UI_LANG==='fr'?fr:en;
function usageSettings(wrap){
 const uid=usageAccount(),epoch=fbEpoch,card=setSection(wrap,usageText('使用统计','Usage statistics','Statistiques d’utilisation'));
 const note=usageText('登录后默认统计页面可见时长，仅管理员可查看每日时长及各板块做题数量。切到后台不计时，同账号重叠时段不重复累计；不记录输入内容或录音。可关闭本浏览器的后续时长统计，已有学习记录仍用于做题分布。','When signed in, visible-page time is measured by default. Only administrators can see daily time and practice counts. Background time is excluded and overlapping time is counted once per account. No input or recordings are collected. You can stop future time measurement in this browser; existing study records still provide practice totals.','Après connexion, le temps de page visible est mesuré par défaut. Seuls les administrateurs voient les durées et nombres d’exercices par jour. L’arrière-plan est exclu et les périodes simultanées ne sont comptées qu’une fois par compte. Aucun texte saisi ni enregistrement audio n’est collecté. Vous pouvez arrêter la mesure future dans ce navigateur ; les acquis existants servent toujours aux totaux d’exercices.');
 card.append(el('p','sub',note));
 const row=setCheckRow('usageEnabled',usageText('统计页面可见时长','Measure visible-page time','Mesurer le temps de page visible'),usageEnabled(uid),value=>{if(fbCurrent(uid,epoch))usageSetEnabled(value);});
 row.querySelector('input').disabled=!uid;card.append(row);
 if(!uid)card.append(el('p','sub',usageText('登录后生效；未登录访问不上传时长。','Applies after sign-in; guest visits do not upload time.','Actif après connexion ; les visites anonymes n’envoient aucune durée.')));
 if(typeof funnelEnabled==='function'){
  card.append(el('p','sub',usageText('匿名访问统计：为了知道新访客在哪一步离开，网站会给这个浏览器一个随机编号，每天最多记四件事——看过首页、打开法语页、答过题、做完一组，以及界面语言和第一题所在的板块。不含账号、网址和答题内容，未登录也会记录。浏览器开启“请勿跟踪”时不记录，也可以在这里关闭。','Anonymous visit statistics: to see where new visitors leave, the site gives this browser a random id and records at most four things a day — saw the home page, opened the French page, answered a question, finished a set — plus the interface language and the section of the first answer. No account, URL or answer content; guests are included. Nothing is recorded when the browser sends Do Not Track, and you can switch it off here.','Statistiques de visite anonymes : pour savoir où les nouveaux visiteurs s’arrêtent, le site attribue à ce navigateur un identifiant aléatoire et note au plus quatre choses par jour — page d’accueil vue, page de français ouverte, une question répondue, une série terminée — ainsi que la langue de l’interface et la rubrique de la première réponse. Ni compte, ni adresse, ni contenu des réponses ; les visites sans connexion sont incluses. Rien n’est noté si le navigateur envoie « Ne pas me pister », et vous pouvez le désactiver ici.')));
  card.append(setCheckRow('funnelEnabled',usageText('匿名访问统计','Anonymous visit statistics','Statistiques de visite anonymes'),funnelEnabled(),value=>funnelSetEnabled(value)));
 }
}
function usageAdminEntry(wrap){
 const uid=usageAccount(),epoch=fbEpoch;if(!uid)return;
 fbRpc('feedback_status').then(result=>{
  if(result.is_admin)try{localStorage.setItem('quiz-funnel-admin','1');}catch(e){} // 管理员自己的浏览器不计入访问漏斗
  if(!result.is_admin||!wrap.isConnected||!fbCurrent(uid,epoch))return;
  const card=setSection(wrap,usageText('管理员统计','Administrator statistics','Statistiques administrateur'));card.classList.add('fb-admin');
  const go=fbButton(usageText('查看使用统计','View usage statistics','Voir les statistiques'),'btn');go.addEventListener('click',()=>{if(fbCurrent(uid,epoch))renderUsageAdmin();});card.append(go);
 }).catch(()=>{});
}
function usageDuration(value){const s=Math.max(0,Math.round(Number(value)||0));if(!s)return '—';return Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m '+s%60+'s';}

// UTC windows include today. Chart data uses the full daily report, never the paginated account list.
function usageRecentRange(days,now=Date.now()){
 const end=new Date(now).toISOString().slice(0,10),start=new Date(Date.parse(end)-(days-1)*86400000).toISOString().slice(0,10);
 return {from:start,to:end};
}
function usageTrendRows(rows,from,to){
 const byDay=new Map(rows.map(r=>[r.day,r])),out=[];
 for(let t=Date.parse(from);t<=Date.parse(to);t+=86400000){
  const day=new Date(t).toISOString().slice(0,10),r=byDay.get(day)||{},row={day};
  for(const key of ['active_users','grammar','conjugation','vocabulary','listening','oral','exams'])row[key]=Math.max(0,Number(r[key])||0);
  row.seconds=Number(r.timed_users)>0?Math.max(0,Number(r.seconds)||0):null;out.push(row);
 }
 return out;
}
function usageTrendCharts(daily,from,to){
 const rows=usageTrendRows(daily,from,to),section=el('section','usage-trends');
 section.append(el('h3',null,usageText('每日趋势','Daily trends','Évolution quotidienne')),
  el('p','sub',usageText('活跃用户指当天有已同步作答、完成任务或可见时长的去重账号。今天尚未结束；时长仅覆盖开启统计的用户，空白表示没有时长记录。可选择日期查看三张图的具体数值，完整数据见下方每日分布。','Active users are distinct accounts with synced attempts, completed tasks or visible time that day. Today is incomplete. Time covers users who enabled measurement; gaps mean no time record. Select a date for exact values in all three charts; the daily table below contains all data.','Les utilisateurs actifs sont les comptes distincts ayant des tentatives synchronisées, des missions terminées ou du temps visible ce jour-là. Aujourd’hui est incomplet. Les durées concernent les utilisateurs ayant activé la mesure ; les lacunes indiquent l’absence de relevé. Choisissez une date pour les valeurs des trois graphiques ; le tableau quotidien contient toutes les données.')));
 const picker=el('select'),label=el('label','usage-trend-picker',usageText('查看日期（UTC）','Inspect date (UTC)','Voir la date (UTC)'));
 picker.setAttribute('aria-label',label.textContent);for(const row of rows){const option=el('option',null,row.day);option.value=row.day;picker.append(option);}picker.value=rows.at(-1)?.day||'';label.append(picker);section.append(label);
 const svgNode=(tag,attrs={},text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;};
 const specs=[
  {id:'active',title:usageText('每日活跃用户','Daily active users','Utilisateurs actifs par jour'),unit:usageText('人','Users','Utilisateurs'),series:[['active_users',usageText('活跃用户','Active users','Utilisateurs actifs'),'#2584db']]},
  {id:'time',title:usageText('每日使用时长','Daily visible time','Temps visible par jour'),unit:usageText('分钟','Minutes','Minutes'),series:[['seconds',usageText('可见时长','Visible time','Temps visible'),'#1a9a88']]},
  {id:'practice',title:usageText('各板块每日做题数量','Daily practice by area','Exercices quotidiens par domaine'),unit:usageText('次数','Count','Nombre'),series:[
   ['grammar',usageText('语法','Grammar','Grammaire'),'#2584db'],['conjugation',usageText('变位','Conjugation','Conjugaison'),'#c17a10'],['vocabulary',usageText('词汇','Vocabulary','Vocabulaire'),'#1a9a88'],['listening',usageText('听力','Listening','Écoute'),'#aa62d3'],['oral',usageText('口语任务','Speaking tasks','Missions orales'),'#dc6574'],['exams',usageText('模拟卷（份）','Exams (papers)','Examens (copies)'),'#829097']]}
 ];
 const updates=[];
 for(const spec of specs){
  const card=el('section','usage-trend-card');card.dataset.chart=spec.id;card.append(el('h4',null,spec.title));
  const svg=svgNode('svg',{viewBox:'0 0 600 260',role:'img','aria-label':spec.title+' · '+from+' – '+to});svg.append(svgNode('title',{},spec.title));
  const left=62,right=574,top=30,bottom=214,x=i=>rows.length===1?(left+right)/2:left+(right-left)*i/(rows.length-1);
  const number=(row,key)=>row[key]===null?null:key==='seconds'?row[key]/60:row[key];
  const observed=spec.series.flatMap(([key])=>rows.map(r=>number(r,key))).filter(v=>v!==null);
  const maximum=Math.max(0,...observed),rawStep=maximum/4,power=10**Math.floor(Math.log10(rawStep||1)),step=maximum?([1,2,5,10].find(n=>n*power>=rawStep)||10)*power:1;
  const tickStep=spec.id==='time'?step:Math.max(1,step),ceiling=Math.max(tickStep,Math.ceil(maximum/tickStep)*tickStep),y=v=>bottom-(bottom-top)*v/ceiling;
  const fmt=v=>new Intl.NumberFormat(typeof UI_LANG==='undefined'?'zh':UI_LANG,{maximumFractionDigits:2}).format(v);
  svg.append(svgNode('text',{x:left,y:18,class:'usage-chart-axis'},spec.unit));
  for(let v=0;v<=ceiling+tickStep/100;v+=tickStep){svg.append(svgNode('line',{x1:left,x2:right,y1:y(v),y2:y(v),class:'usage-chart-grid'}),svgNode('text',{x:left-9,y:y(v)+5,'text-anchor':'end',class:'usage-chart-axis'},fmt(v)));}
  for(const i of new Set([0,Math.floor((rows.length-1)/2),rows.length-1]))if(rows[i])svg.append(svgNode('text',{x:x(i),y:244,'text-anchor':i===0?'start':i===rows.length-1?'end':'middle',class:'usage-chart-axis'},rows[i].day.slice(5)));
  const cursor=svgNode('line',{x1:right,x2:right,y1:top,y2:bottom,class:'usage-chart-cursor'});svg.append(cursor);
  const legend=el('div','usage-trend-legend');
  spec.series.forEach(([key,name,color],seriesIndex)=>{
   let path='',connected=false;
   rows.forEach((r,i)=>{const value=number(r,key);if(value===null){connected=false;return;}path+=(connected?' L ':' M ')+x(i)+','+y(value);connected=true;});
   const attrs={d:path,fill:'none',stroke:color,'stroke-width':2.5,'stroke-linejoin':'round','stroke-linecap':'round','data-series':key};
   if(seriesIndex>=4)attrs['stroke-dasharray']=seriesIndex===4?'7 4':'2 4';svg.append(svgNode('path',attrs));
   rows.forEach((r,i)=>{const value=number(r,key);if(value===null)return;const dot=svgNode('circle',{cx:x(i),cy:y(value),r:rows.length>7?2:3,fill:color});dot.append(svgNode('title',{},r.day+' · '+name+': '+(key==='seconds'?usageDuration(r[key]):fmt(value))));svg.append(dot);});
   const item=el('span'),swatch=el('i');swatch.style.borderColor=color;if(seriesIndex>=4)swatch.style.borderTopStyle=seriesIndex===4?'dashed':'dotted';swatch.setAttribute('aria-hidden','true');item.append(swatch,document.createTextNode(name));legend.append(item);
  });
  const readout=el('p','usage-trend-readout');readout.setAttribute('aria-live','polite');
  updates.push(index=>{const row=rows[index];if(!row)return;cursor.setAttribute('x1',x(index));cursor.setAttribute('x2',x(index));readout.textContent=row.day+' · '+spec.series.map(([key,name])=>name+': '+(row[key]===null?'—':key==='seconds'?usageDuration(row[key]):fmt(row[key]))).join(' · ');});
  card.append(svg,legend,readout);
  if(!observed.length)card.append(el('p','sub',usageText('这段时间没有可见时长记录。','No visible-time records in this range.','Aucune durée visible enregistrée sur cette période.')));
  section.append(card);
 }
 const select=()=>{const index=rows.findIndex(r=>r.day===picker.value);updates.forEach(update=>update(index));};picker.addEventListener('change',select);select();return section;
}

// 新访客漏斗：按“第一次打开法语页的那天”分组；隔天、7 天内的数字要等够天数才算数，没等够的标“…”。
function usageFunnelTable(data){
 const section=el('section','usage-funnel');section.append(el('h3',null,usageText('新访客漏斗（含未登录）','New-visitor funnel (guests included)','Entonnoir des nouveaux visiteurs (anonymes inclus)')));
 section.append(el('p','sub',usageText('每个浏览器一个匿名编号，按访客自己的日期计。“新访客”是第一次打开法语页的浏览器；清过缓存或换设备会被算成新访客，所以回访率是下限。从 v1.9.83 上线那天起才有数据，上线头几天的“新访客”里包含老用户。','One anonymous id per browser, dated by the visitor’s own calendar. A new visitor is a browser opening the French page for the first time; cleared storage or a second device counts as new, so return rates are a lower bound. Data starts with v1.9.83, and the first days include existing users.','Un identifiant anonyme par navigateur, daté selon le calendrier du visiteur. Un nouveau visiteur est un navigateur qui ouvre la page de français pour la première fois ; un stockage effacé ou un second appareil compte comme nouveau, donc les taux de retour sont un minimum. Les données commencent avec la v1.9.83 et les premiers jours incluent les anciens utilisateurs.')));
 const today=Date.parse(data.today),age=day=>Math.round((today-Date.parse(day))/86400000),pct=(n,d)=>d?n+' ('+Math.round(n/d*100)+'%)':'0';
 const heads=[usageText('首次访问日','First visit','Première visite'),usageText('新访客','New visitors','Nouveaux'),usageText('当天答过题','Answered that day','Ont répondu ce jour'),usageText('当天做完一组','Finished a set that day','Série terminée ce jour'),usageText('7 天内答过题','Answered within 7 days','Ont répondu sous 7 j'),usageText('第二天回来','Back next day','Revenus le lendemain'),usageText('7 天内回来','Back within 7 days','Revenus sous 7 j'),usageText('第 7 天后还在','Still here after day 7','Encore là après 7 j')];
 const row=(label,c,a)=>[label,c.devices,pct(c.answered,c.devices),pct(c.finished,c.devices),pct(c.answered_w1,c.devices)+(a<7?' …':''),a<1?'…':pct(c.back_d1,c.devices)+(a<2?' …':''),a<1?'…':pct(c.back_w1,c.devices)+(a<8?' …':''),a<7?'…':pct(c.back_d7,c.devices)+' …'];
 const sum=(list,keys)=>list.reduce((t,c)=>{for(const k of keys)t[k]=(t[k]||0)+Number(c[k]);return t;},{});
 const keys=['devices','answered','finished','answered_w1','back_d1','back_w1','back_d7'],all=sum(data.cohorts,keys),done=sum(data.cohorts.filter(c=>age(c.day)>=8),keys);
 const wrap=el('div','usage-table-wrap'),t=el('table','usage-table'),head=el('thead'),hr=el('tr'),body=el('tbody');for(const h of heads){const th=el('th',null,h);th.scope='col';hr.append(th);}head.append(hr);t.append(head,body);wrap.append(t);
 const add=cells=>{const tr=el('tr');for(const v of cells)tr.append(el('td',null,String(v)));body.append(tr);};
 if(data.cohorts.length){add(row(usageText('合计','Total','Total'),{...Object.fromEntries(keys.map(k=>[k,0])),...all},0).map((v,i)=>i>3?'—':v));if(done.devices)add(row(usageText('已满 8 天的合计','Total, cohorts 8+ days old','Total, cohortes de 8 j et plus'),done,99).map((v,i)=>i===7?String(v).replace(' …',''):v));}
 for(const c of [...data.cohorts].reverse())add(row(c.day,c,age(c.day)));
 section.append(wrap);if(!data.cohorts.length)section.append(el('p','sub',usageText('此范围暂无访客数据。','No visitor data in this range.','Aucune donnée de visite sur cette période.')));
 const home=sum(data.home,['devices','opened']),active=sum(data.active,['devices']),names={grammar:usageText('语法','Grammar','Grammaire'),listening:usageText('听力','Listening','Écoute'),vocab:usageText('词汇','Vocabulary','Vocabulaire'),conj:usageText('变位','Conjugation','Conjugaison'),exam:usageText('模拟卷','Exam','Examen'),other:usageText('其他','Other','Autre'),none:usageText('当天没答题','No answer that day','Aucune réponse ce jour'),zh:'中文',en:'English',fr:'Français'};
 const list=o=>Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([k,n])=>(names[k]||k)+' '+n).join(' · ')||'—';
 section.append(el('p','usage-summary',usageText('首页：','Home page: ','Accueil : ')+(home.devices||0)+usageText(' 次访问（按浏览器·天），其中 ',' browser-days, of which ',' navigateurs-jours, dont ')+pct(home.opened||0,home.devices||0)+usageText(' 当天进了法语页',' opened the French page that day',' ont ouvert la page de français ce jour')+' · '+usageText('法语页活跃：','French page active: ','Page de français active : ')+(active.devices||0)+usageText('（浏览器·天）',' browser-days',' navigateurs-jours')));
 section.append(el('p','sub',usageText('新访客第一题所在板块：','Section of new visitors’ first answer: ','Rubrique de la première réponse : ')+list(data.sections)),el('p','sub',usageText('新访客界面语言：','New visitors’ interface language: ','Langue de l’interface : ')+list(data.langs)));
 return section;
}
function renderUsageAdmin(){
 const uid=usageAccount(),epoch=fbEpoch;if(!uid)return;
 stage.innerHTML='';const root=el('section','card fb-admin usage-admin');root.dataset.noi18n='';stage.append(root);
 const current=()=>root.isConnected&&fbCurrent(uid,epoch);
 const back=fbButton(usageText('返回设置','Back to settings','Retour aux réglages'),'btn ghost');back.addEventListener('click',renderSettings);
 root.append(back,el('h2',null,usageText('每日使用与做题统计','Daily usage and practice','Utilisation et exercices par jour')),
  el('p','sub',usageText('按 UTC 日期统计，仅包含已登录账号的云端数据。时长从 v1.9.35 上线后开始，表示页面可见的估算停留时长，不等同于专注学习；突然关闭可能少计最后约 30 秒。无时长记录以 — 显示。做题按作答次数计，重做也计入；口语仅计已完成任务，模拟卷按交卷份数单列。','Dates use UTC; only signed-in cloud records are included. Time starts with v1.9.35 and estimates visible-page duration, not focused study. An abrupt close may lose about 30 seconds. A dash means no time record. Practice counts attempts, including repeats; speaking counts completed tasks and exams count submitted papers separately.','Dates en UTC ; seules les données synchronisées des comptes connectés sont incluses. Les durées commencent avec la version 1.9.35 et estiment le temps de page visible, pas la concentration. Une fermeture brutale peut perdre environ 30 secondes. Un tiret indique l’absence de durée enregistrée. Les exercices comptent les tentatives, y compris répétées ; l’oral compte les missions terminées et les examens les copies remises.')));
 const form=el('div','usage-filters'),from=el('input'),to=el('input'),go=fbButton(usageText('查询','Load','Afficher'),'btn');from.type=to.type='date';
 const initial=usageRecentRange(7);to.value=initial.to;from.value=initial.from;
 const quick=el('div','usage-presets'),presets=[];quick.setAttribute('role','group');quick.setAttribute('aria-label',usageText('快捷日期范围','Quick date range','Période rapide'));
 for(const days of [7,30]){const button=fbButton(usageText('最近 '+days+' 天','Last '+days+' days',days+' derniers jours'),'btn ghost');button.dataset.days=days;button.addEventListener('click',()=>{if(busy)return;const range=usageRecentRange(days);from.value=range.from;to.value=range.to;page=0;void load();});presets.push([days,button]);quick.append(button);}
 const updatePresets=()=>{for(const [days,button]of presets){const range=usageRecentRange(days);button.setAttribute('aria-pressed',String(from.value===range.from&&to.value===range.to));}};from.addEventListener('change',updatePresets);to.addEventListener('change',updatePresets);updatePresets();
 for(const [input,label]of [[from,usageText('开始日期','Start date','Date de début')],[to,usageText('结束日期','End date','Date de fin')]]){const l=el('label',null,label);input.setAttribute('aria-label',label);l.append(input);form.append(l);}
 form.append(go);const status=el('p','sub'),content=el('div','usage-results');status.setAttribute('role','status');root.append(quick,form,status,content);
 let selected=null,page=0,busy=false;
 const headings=[usageText('可见时长','Visible time','Temps visible'),usageText('语法','Grammar','Grammaire'),usageText('变位','Conjugation','Conjugaison'),usageText('词汇','Vocabulary','Vocabulaire'),usageText('听力','Listening','Écoute'),usageText('口语任务','Speaking tasks','Missions orales'),usageText('模拟卷（份）','Exams (papers)','Examens (copies)')];
 const values=r=>[usageDuration(r.seconds),r.grammar,r.conjugation,r.vocabulary,r.listening,r.oral,r.exams];
 function table(title,headers,rows){const section=el('section');section.append(el('h3',null,title));const scroll=el('div','usage-table-wrap'),t=el('table','usage-table'),head=el('thead'),tr=el('tr');for(const h of headers){const th=el('th',null,h);th.scope='col';tr.append(th);}head.append(tr);t.append(head);const body=el('tbody');for(const row of rows){const tr=el('tr');for(const value of row){const td=el('td');if(value?.nodeType)td.append(value);else td.textContent=String(value??0);tr.append(td);}body.append(tr);}t.append(body);scroll.append(t);section.append(scroll);content.append(section);}
 async function load(){
  if(busy||!current())return;updatePresets();
  const span=(Date.parse(to.value)-Date.parse(from.value))/86400000;
  if(!from.value||!to.value||!Number.isFinite(span)||span<0||span>30){content.replaceChildren();status.textContent=usageText('请选择不超过 31 天的日期范围。','Choose a range of up to 31 days.','Choisissez une période de 31 jours maximum.');return;}
  busy=true;go.disabled=from.disabled=to.disabled=true;presets.forEach(([,b])=>b.disabled=true);content.querySelectorAll('button').forEach(b=>b.disabled=true);status.textContent=fbText('loading');
  try{
   const data=await fbRpc('admin_learning_usage',{p_from:from.value,p_to:to.value,p_user:selected,p_page:page});if(!current())return;
   content.replaceChildren();status.textContent='';
   const total=data.daily.reduce((a,r)=>{for(const k of ['seconds','grammar','conjugation','vocabulary','listening','oral','exams'])a[k]=(a[k]||0)+Number(r[k]);return a;},{});
   content.append(el('p','usage-summary',usageText('范围内账号：','Accounts in range: ','Comptes sur la période : ')+data.user_count+' · '+usageText('可见时长：','Visible time: ','Temps visible : ')+usageDuration(total.seconds)+' · '+usageText('作答次数：','Attempts: ','Tentatives : ')+(total.grammar+total.conjugation+total.vocabulary+total.listening)));
   if(selected){const clear=fbButton(usageText('查看全部账号','All accounts','Tous les comptes'));clear.addEventListener('click',()=>{selected=null;page=0;void load();});content.append(el('p','sub',usageText('当前账号：','Selected account: ','Compte sélectionné : ')+selected.slice(0,8)),clear);}
   content.append(usageTrendCharts(data.daily,from.value,to.value));
   const chart=el('div','usage-distribution');const count=total.grammar+total.conjugation+total.vocabulary+total.listening;
   for(const [k,label]of [['grammar',headings[1]],['conjugation',headings[2]],['vocabulary',headings[3]],['listening',headings[4]]]){const row=el('div','usage-bar');row.append(el('span',null,label+' · '+total[k]));const bar=el('progress');bar.max=Math.max(1,count);bar.value=total[k];bar.setAttribute('aria-label',label);row.append(bar);chart.append(row);}content.append(chart);
   table(usageText('每日分布','Daily distribution','Répartition quotidienne'),[usageText('日期（UTC）','Date (UTC)','Date (UTC)'),usageText('活跃账号','Active accounts','Comptes actifs'),...headings],data.daily.map(r=>[r.day,r.active_users,...values(r)]));
   table(usageText('账号明细','Account details','Détail des comptes'),[usageText('账号','Account','Compte'),...headings,usageText('每日详情','Daily detail','Détail quotidien')],data.users.map(r=>{const b=fbButton(usageText('查看','View','Voir'));b.addEventListener('click',()=>{selected=r.user_id;page=0;void load();});return [(r.nick||usageText('用户','User','Utilisateur'))+' · '+r.user_id.slice(0,8),...values(r),b];}));
   if(!data.user_count)content.append(el('p','sub',usageText('此范围暂无统计数据。','No data in this range.','Aucune donnée sur cette période.')));
   if(!selected){const slot=el('div');content.append(slot);fbRpc('admin_funnel',{p_from:from.value,p_to:to.value}).then(f=>{if(current()&&slot.isConnected)slot.append(usageFunnelTable(f));}).catch(()=>{if(current()&&slot.isConnected)slot.append(el('p','sub',usageText('新访客漏斗暂时读不到：请确认已在数据库里运行 funnel.sql。','The visitor funnel is unavailable: check that funnel.sql has been applied to the database.','Entonnoir indisponible : vérifiez que funnel.sql a été appliqué à la base.')));});}
   const nav=el('div','actions');for(const [delta,label]of [[-1,usageText('上一页','Previous','Précédent')],[1,usageText('下一页','Next','Suivant')]]){const b=fbButton(label);b.disabled=delta<0?page===0:(page+1)*50>=data.user_count;b.addEventListener('click',()=>{page+=delta;void load();});nav.append(b);}content.append(nav);
  }catch(e){if(current()&&e.code!=='account'){content.replaceChildren();status.textContent=usageText('无法读取统计，请确认管理员权限后重试。','Unable to load statistics. Check administrator access and retry.','Impossible de charger les statistiques. Vérifiez vos droits administrateur et réessayez.');}}
  finally{busy=false;if(current()){go.disabled=from.disabled=to.disabled=false;presets.forEach(([,b])=>b.disabled=false);}}
 }
 go.addEventListener('click',()=>{page=0;void usageFlush().then(load);});void usageFlush().then(load);
}
// ---------- 设置：集中管理各模块的练习设置（都记在本机浏览器里） ----------
function renderSettings() {
  stage.innerHTML = "";
  const wrap = el("div", "set-page");
  let target;
  const section = (title, sub) => setSection(target, title, sub);
  const selectRow = setSelectRow, checkRow = setCheckRow;

  setAccountSection(wrap);   // 账号与同步放最上面
  target = setFold(wrap, "settings-function", "功能设置");
  setGoalSection(target);
  usageSettings(target);

  // 界面语言
  const lg = section("界面语言", "切换后页面会重新载入。界面和解析使用所选语言，题目里的法语不变。中文、英文、法语模式答对所得金币分别为 ×1、×2、×3；切换不影响过去的金币。");
  const lockNote = "（商店解锁）";
  lg.append(selectRow("setLang", "界面语言", [["zh", "中文"], ["en", setOwned("lang-en") ? "English" : "English" + lockNote], ["fr", setOwned("lang-fr") ? "Français" : "Français" + lockNote]], UI_LANG, val => setUiLang(val)));

  // 字体
  const ft = section("字体", "影响英文和法语字母；汉字仍用思源黑体 / 宋体。");
  ft.append(selectRow("setFont", "字体", [["default", "默认"], ["times", "Times New Roman" + (setOwned("font-times") ? "" : lockNote)], ["kreon", "Kreon" + (setOwned("font-kreon") ? "" : lockNote)]], UI_FONT, val => setUiFont(val)));
  // 没买的选项不能选
  [["setLang", "fr", "lang-fr"], ["setLang", "en", "lang-en"], ["setFont", "times", "font-times"], ["setFont", "kreon", "font-kreon"]].forEach(([sid, v, item]) => { const o = wrap.querySelector(`#${sid} option[value="${v}"]`); if (o && !setOwned(item)) o.disabled = true; });
  if (!(setOwned("lang-en") && setOwned("lang-fr") && setOwned("font-times") && setOwned("font-kreon"))) lg.append(el("p", "sub", "英文、法语界面和字体要先在“商店 · 设置”里用金币解锁。"));

  target = setFold(wrap, "settings-practice", "做题设置");
  qlSection(target);
  setQuizSection(target);

  // 词汇
  const v = section("词汇", "难度为“困难”时，干扰选项优先用易混词（意思、用法容易混，如 prêter / emprunter），再用拼写相近的词，答完显示辨析。");
  v.append(selectRow("setVPer", "每组词数", [5, 10, 15, 20].map(n => [n, `${n} 个词`]), vPer, val => {
    vPer = Number(val); try { localStorage.setItem("fq-vper", String(vPer)); } catch (e) {}
  }), ...vSetRows());

  // 变位
  const c = section("变位", "时态和动词组在“变位”页左侧选择。");
  c.append(
    selectRow("setCjMode", "出题方式", [["pick", "选择"], ["type", "填空"]], cjCfg.mode, val => { cjCfg.mode = val; cjSaveCfg(); cjSess = null; }),
    selectRow("setCjN", "每组题数", [[10, "10 题"], [20, "20 题"], [30, "30 题"], [0, "不限"]], cjCfg.n, val => { cjCfg.n = Number(val); cjSaveCfg(); cjSess = null; }));

  // 朗读
  studyAudioSettings(target);
  const r = section("朗读");
  r.append(checkRow("setRead", "答完自动朗读单词（词汇和变位）", vSet.read, val => { vSet.read = val; vSaveSet(); }));
  if (tts) {
    const voice = frVoice || pickVoice();
    r.append(el("p", "sub", voice ? `朗读用的声音：${voice.name}（${voice.lang}）。想换更好听的声音，可以在系统设置的“辅助功能 → 朗读内容 → 声音”里下载法语的增强版声音。` : "这台设备上没找到法语朗读声音，可以在系统设置里添加法语语音。"));
  } else r.append(el("p", "sub", "这个浏览器不支持朗读。"));

  feedbackSettings(setFold(wrap, "settings-feedback", "留言板"));
  shareSettings(wrap);
  surveySettings(wrap);
  target = setFold(wrap, "settings-game", "游戏设置");
  setGameSection(target);
  petSettings(target);
  pomoEntry(target);

  wrap.append(tokenSupportCard());
  { const slot = el("div"); slot.style.display = "contents"; wrap.append(slot); lazyLoad("changelog").then(() => { if (slot.isConnected) changelogCard(slot, "fr"); }, () => {}); }   // 版本号和更新记录（数据用到时再加载）
  wrap.append(el("p", "sub set-foot", "设置只保存在这台设备的浏览器里，改动马上生效（词汇的题型从下一组开始）。"));
  stage.append(wrap);
  usageAdminEntry(wrap);
}


// Fill only with the owner's supplied payment assets/hosted checkout URL.
// Static collection QR codes do not set or verify the transferred amount.
const TOKEN_SUPPORT = { wechat: "support/wechat.jpg", alipay: "support/alipay.jpg", cardUrl: null };
function tokenSupportCard() {
 const copies={
  zh:{intro:'如果这个网站对你有帮助，欢迎支持后续开发。',amount:'打赏金额（人民币）',custom:'自定义金额',method:'支付方式',wechat:'微信',alipay:'支付宝',credit:'信用卡',pending:'收款码接入中',invalid:'请输入大于 0 的金额，最多两位小数。',pay:'请在支付应用中填写此金额：',note:'扫码后请核对收款人和金额。网站不会自动确认付款。',close:'收起',open:'打开安全支付页面',original:'查看／保存收款码原图',thanks:'谢谢你支持学习伙伴！'},
  en:{intro:'If this website helps you, you can support its continued development.',amount:'Amount (CNY)',custom:'Custom amount',method:'Payment method',wechat:'WeChat Pay',alipay:'Alipay',credit:'Credit card',pending:'Payment QR code coming soon',invalid:'Enter a positive amount with up to two decimal places.',pay:'Enter this amount in your payment app: ',note:'Check the recipient and amount after scanning. This website does not automatically confirm payment.',close:'Close',open:'Open secure checkout',original:'View / save original payment code',thanks:'Thank you for supporting your learning companion!'},
  fr:{intro:'Si ce site vous aide, vous pouvez soutenir son développement.',amount:'Montant (CNY)',custom:'Montant libre',method:'Moyen de paiement',wechat:'WeChat Pay',alipay:'Alipay',credit:'Carte bancaire',pending:'Code de paiement bientôt disponible',invalid:'Saisissez un montant positif avec au maximum deux décimales.',pay:'Saisissez ce montant dans votre application de paiement : ',note:'Vérifiez le destinataire et le montant après le scan. Ce site ne confirme pas automatiquement le paiement.',close:'Fermer',open:'Ouvrir le paiement sécurisé',original:'Voir / enregistrer le code original',thanks:'Merci de soutenir votre compagnon !'}
 };
 const t=copies[UI_LANG]||copies.zh;
 const root=el('section','card token-support');root.dataset.noi18n='';
 const toggle=fbButton('Buy me some Tokens','btn token-support-toggle'),panel=el('div','token-support-panel');panel.hidden=true;toggle.setAttribute('aria-expanded','false');panel.id='tokenSupportPanel';toggle.setAttribute('aria-controls',panel.id);
 toggle.addEventListener('click',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));});
 panel.append(el('p','sub',t.intro));
 const amounts=el('fieldset'),legend=el('legend',null,t.amount);amounts.append(legend);
 const choices=el('div','token-support-choices'),custom=el('input');custom.type='text';custom.inputMode='decimal';custom.autocomplete='off';custom.placeholder=t.custom;custom.setAttribute('aria-label',t.custom);custom.maxLength=12;
 let amount='3',method='wechat';const buttons=[];
 const methods=el('fieldset');methods.append(el('legend',null,t.method));const methodButtons=[];
 const result=el('div','token-support-result');result.setAttribute('aria-live','polite');
 const draw=()=>{
  buttons.forEach(([b,v])=>b.setAttribute('aria-pressed',String(amount===v&&!custom.value)));
  methodButtons.forEach(([b,v])=>b.setAttribute('aria-pressed',String(method===v)));
  result.replaceChildren();const value=custom.value.trim()||amount;
  if(!/^(?:0|[1-9]\d{0,8})(?:\.\d{1,2})?$/.test(value)||Number(value)<=0){result.append(el('p','sub',t.invalid));return;}
  result.append(el('strong',null,t.pay+'¥'+Number(value).toFixed(2)));
  if(method==='card'){const a=el('a','btn',t.open);a.href=TOKEN_SUPPORT.cardUrl;a.target='_blank';a.rel='noopener noreferrer';result.append(a);return;}
  const src=TOKEN_SUPPORT[method];if(!src){result.append(el('p','sub',t.pending));return;}
  const img=el('img','token-support-qr');img.src=src;img.alt=t[method];const frame=el('div','token-support-frame');frame.dataset.method=method;const header=el('div','token-support-frame-head');header.append(el('b',null,'Buy me some Tokens'));const friends=el('div','token-support-friends');friends.append(petImage('ninon','idle','', ''),el('span',null,t.thanks),petImage('pia','idle','', ''));frame.append(header,img,friends);const original=el('a','token-support-original',t.original);original.href=src;original.target='_blank';original.rel='noopener noreferrer';result.append(frame,original,el('p','sub',t.note));
 };
 for(const n of ['1','3','5','10']){const b=fbButton('¥'+n);b.addEventListener('click',()=>{amount=n;custom.value='';draw();});buttons.push([b,n]);choices.append(b);}
 custom.addEventListener('input',draw);amounts.append(choices,custom);
 for(const key of ['wechat','alipay',...(TOKEN_SUPPORT.cardUrl?['card']:[])]){const b=fbButton(t[key==='card'?'credit':key]);b.addEventListener('click',()=>{method=key;draw();});methodButtons.push([b,key]);methods.append(b);}
 panel.append(amounts,methods,result);root.append(toggle,panel);draw();return root;
}
